import {Vector3,Quaternion,Matrix4,Matrix3} from 'three';

export const wheelVisualDefaults=()=>({bone:'',steerAxis:[0,1,0],spinAxis:[1,0,0],steerScale:1,spinScale:-1,suspensionScale:1});
const fields=new Set(Object.keys(wheelVisualDefaults())),axis=v=>Array.isArray(v)&&v.length===3&&v.every(x=>Number.isFinite(x)&&Math.abs(x)<=10000)&&Math.hypot(...v)>1e-8,owners=new WeakMap();
export function validWheelVisual(value){if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!fields.has(k)))return false;const p={...wheelVisualDefaults(),...value};return typeof p.bone==='string'&&p.bone.length<=160&&axis(p.steerAxis)&&axis(p.spinAxis)&&[p.steerScale,p.spinScale,p.suspensionScale].every(v=>Number.isFinite(v)&&Math.abs(v)<=100);}
export function physicalVehicleWheels(wheels){return wheels.some(w=>w.visual!==undefined)?wheels.map(w=>{if(w.visual===undefined)return w;const {visual,...physical}=w;return physical;}):wheels;}

export class VehicleWheelBones{
 constructor(group,wheels){
  this.group=group;this.rows=[];this.parents=new Map();this.position=new Vector3();this.bodyRotation=new Quaternion();this.scale=new Vector3();this.down=new Vector3();this.turn=new Quaternion();this.spin=new Quaternion();this.disposed=false;const names=new Map();group.traverse(b=>{if(b.isBone){const list=names.get(b.name)||[];list.push(b);names.set(b.name,list);}});
  for(const [index,w] of wheels.entries()){const p={...wheelVisualDefaults(),...w.visual};if(!p.bone)continue;if(!validWheelVisual(w.visual))throw Error('차량 휠 뼈 설정을 확인하세요.');const found=names.get(p.bone);if(found?.length!==1)throw Error('차량 휠 뼈의 고유 이름을 확인하세요: '+p.bone);const bone=found[0];if(!bone.parent||this.rows.some(row=>row.bone===bone))throw Error('차량 휠 뼈를 중복 지정할 수 없어요: '+p.bone);let parent=this.parents.get(bone.parent);if(!parent){parent={bone:bone.parent,inverse:new Matrix4(),linear:new Matrix3()};this.parents.set(bone.parent,parent);}this.rows.push({bone,index,w,p,parent,steerAxis:new Vector3(...p.steerAxis).normalize(),spinAxis:new Vector3(...p.spinAxis).normalize(),basePosition:bone.position.clone(),baseRotation:bone.quaternion.clone(),lastPosition:bone.position.clone(),lastRotation:bone.quaternion.clone(),position:new Vector3(),rotation:new Quaternion(),delta:new Vector3(),owned:false,ready:false});}
  const bound=new Set(this.rows.map(row=>row.bone));for(const row of this.rows)for(let p=row.bone.parent;p&&p!==group;p=p.parent)if(bound.has(p))throw Error('차량 휠 뼈끼리 부모·자식으로 지정할 수 없어요.');
  this.debug={bound:this.rows.length,active:0,missingFrames:0,updates:0,restored:0,externalWritesPreserved:0};group.userData.vehicleBoneVisual=this.debug;
 }
 restore(row){if(!row.owned)return;if(owners.get(row.bone)===this){let changed=false;if(row.bone.position.equals(row.lastPosition)){row.bone.position.copy(row.basePosition);changed=true;}else this.debug.externalWritesPreserved++;if(row.bone.quaternion.equals(row.lastRotation)){row.bone.quaternion.copy(row.baseRotation);changed=true;}else this.debug.externalWritesPreserved++;if(changed){row.bone.updateMatrix();row.bone.updateWorldMatrix(true,true);this.debug.restored++;}owners.delete(row.bone);}row.owned=false;}
 apply(state,running){
  if(this.disposed)return;this.debug.active=this.debug.missingFrames=0;if(!running||!state){for(const row of this.rows)this.restore(row);return;}const group=this.group;group.updateWorldMatrix(true,false);group.matrixWorld.decompose(this.position,this.bodyRotation,this.scale);this.down.set(0,-1,0).applyQuaternion(this.bodyRotation);for(const p of this.parents.values()){p.bone.updateWorldMatrix(true,false);const determinant=p.bone.matrixWorld.determinant();if(!Number.isFinite(determinant)||determinant===0)throw Error('차량 휠 뼈의 부모 변환이 겹쳐 있어요.');p.inverse.copy(p.bone.matrixWorld).invert();p.linear.setFromMatrix4(p.inverse);}
  // Prepare every row before committing bone writes; malformed frames cannot
  // leave half a rig updated. Scratch and diagnostics are retained, no frame arrays.
  for(const row of this.rows){const w=state.wheels?.[row.index];row.ready=!!w;if(!w){this.debug.missingFrames++;continue;}if(!Number.isFinite(w.suspension)||!Number.isFinite(w.steering)||!Number.isFinite(w.rotation))throw Error('차량 휠 표시 프레임을 확인하세요.');if(owners.has(row.bone)&&owners.get(row.bone)!==this)throw Error('차량 휠 뼈를 다른 표시기가 사용 중이에요.');if(!row.owned){row.basePosition.copy(row.bone.position);row.baseRotation.copy(row.bone.quaternion);}row.delta.copy(this.down).multiplyScalar((w.suspension-row.w.restLength)*row.p.suspensionScale).applyMatrix3(row.parent.linear);row.position.copy(row.basePosition).add(row.delta);this.turn.setFromAxisAngle(row.steerAxis,(w.steering%(2*Math.PI))*row.p.steerScale);this.spin.setFromAxisAngle(row.spinAxis,(w.rotation%(2*Math.PI))*row.p.spinScale);row.rotation.copy(row.baseRotation).multiply(this.turn).multiply(this.spin).normalize();if(!Number.isFinite(row.position.x)||!Number.isFinite(row.position.y)||!Number.isFinite(row.position.z))throw Error('차량 휠 뼈 이동 범위를 확인하세요.');}
  for(const row of this.rows){if(!row.ready){this.restore(row);continue;}row.bone.position.copy(row.position);row.bone.quaternion.copy(row.rotation);row.bone.updateMatrix();row.lastPosition.copy(row.position);row.lastRotation.copy(row.rotation);row.owned=true;owners.set(row.bone,this);this.debug.active++;}for(const row of this.rows)if(row.ready)row.bone.updateWorldMatrix(false,true);this.debug.updates++;
 }
 dispose(){if(this.disposed)return;for(const row of this.rows)this.restore(row);this.debug.active=0;this.disposed=true;this.rows.length=0;this.parents.clear();this.group=null;}
}
export const vehicleWheelBonesContract={property:'RaycastVehicle.wheels[].visual optional object',fields:wheelVisualDefaults(),pose:'Explicit unique skeleton bone; authored bind position corresponds to wheel rest suspension. World-meter suspension displacement transformed through parent inverse; bind-local steer then spin quaternion axes/scales, reusable scratch, no accumulated frame rotation. Independent of showWheels.',lifetime:'Scene resource ownership; active frame acquires only its configured bones. Stop/missing frame/disposal restores each owned position/quaternion only if it still equals the last driver write, preserving foreign edits. Reacquisition uses the current incoming pose. Nested bound wheels rejected.',physics:'Visual metadata excluded from vehicle-controller rebuild signature and configuration wake-up; existing physical wheel limits/settings/state and native/C++ JSON transport unchanged.',limits:'Visual kinematic wheel bone driver, not tire mesh deformation, full chassis animation/IK/force coupling or a general animation-layer mixer. Duplicate/missing bones fail at build; rebuild imported rig after changing skeleton. No GUI/backend pixels/device or whole-game FPS claim.'};
